<!doctype html><html><head><meta charset="utf-8"><title>Blog</title><style>body{margin:0;background:#f6f4ef;font:14px Arial}.layout{display:grid;grid-template-columns:250px 1fr;min-height:100vh}.side{overflow-y:auto;scrollbar-width:thin;padding:25px 14px;background:linear-gradient(160deg,#15191a,#050606);color:#fff}.side .logo{display:block;margin:0 11px 29px;padding-bottom:23px;border-bottom:1px solid #333}.side .logo img{width:114px}.side .label{margin:0 12px 11px;color:#c9bd9f;font:700 9px Arial;letter-spacing:.24em}.side nav a{display:flex;align-items:center;gap:13px;padding:12px;margin:2px 0;border-left:2px solid transparent;border-radius:6px;color:#f6f4ef;font:14px Georgia;text-decoration:none}.side nav a:hover,.side nav a.active{border-left-color:#c29c53;background:linear-gradient(90deg,rgba(175,137,67,.32),rgba(175,137,67,.08))}.side nav svg{width:18px;height:18px}.main{padding:42px 5%}.top{display:flex;justify-content:space-between;align-items:center}.btn{padding:11px 16px;background:#171717;color:#fff;text-decoration:none;border:0}.success{padding:12px;background:#efe4cd}.table{margin-top:25px;width:100%;border-collapse:collapse;background:#fff}.table th,.table td{padding:15px;text-align:left;border-bottom:1px solid #ddd}.actions{display:flex;align-items:center;gap:8px}.edit-btn,.delete-btn{display:inline-flex;align-items:center;justify-content:center;min-width:68px;padding:8px 12px;border-radius:5px;font:700 13px Arial;text-decoration:none;cursor:pointer}.edit-btn{background:#171717;color:#fff}.edit-btn:hover{background:#6d542f}.delete-btn{border:1px solid #b52b25;background:#fff;color:#a21d16}.delete-btn:hover{background:#fff0ef}.actions form{margin:0}@media(max-width:850px){.layout{grid-template-columns:1fr}.side{padding:14px}.main{padding:25px 18px}}
.resource-heading{margin:22px 12px 8px;color:#c9bd9f;font:700 9px Arial;letter-spacing:.24em}.resource-menu summary{display:flex;align-items:center;gap:13px;padding:12px;margin:2px 0;border-left:2px solid #c29c53;border-radius:6px;color:#f6f4ef;font:14px Georgia;cursor:pointer;list-style:none;background:linear-gradient(90deg,rgba(175,137,67,.32),rgba(175,137,67,.08))}.resource-menu summary::-webkit-details-marker{display:none}.resource-menu summary:after{content:"▶";margin-left:auto;color:#c29c53;font-size:13px;font-family:Arial;transition:transform .2s}.resource-menu[open] summary:after{content:"▼"}.resource-links{margin-left:31px;border-left:1px solid #66532f}.resource-links a{display:block!important;padding:9px 12px!important;margin:0!important;border:0!important;border-radius:0!important;font-size:13px!important}.resource-links a:hover{background:rgba(175,137,67,.18)!important;color:#fff!important}</style></head><body><div class="layout"><aside class="side"><a class="logo" href="{{ route('admin.dashboard') }}"><img src="{{ asset('images/header-logo.png') }}" alt="Niaz Law P.C."></a><p class="label">WEBSITE MANAGEMENT</p><nav><a href="{{ route('admin.home-settings.edit') }}"><x-admin-icon name="home"/>Home Page Setting</a><a href="{{ route('admin.attorneys.create') }}"><x-admin-icon name="user"/>Add Attorney</a><a href="{{ route('admin.attorneys.details') }}"><x-admin-icon name="users"/>Attorney Detail Page</a><a href="{{ route('admin.capabilities.index') }}"><x-admin-icon name="chart"/>Capabilities</a><a href="{{ route('admin.capabilities.pages') }}"><x-admin-icon name="file"/>Capability Pages</a><a href="{{ route('admin.contact-settings.edit') }}"><x-admin-icon name="mail"/>Contact Us</a><p class="resource-heading">INSIGHTS &amp; RESOURCES</p><div class="resource-links"><a class="active" href="{{ route('admin.blog.index') }}"><x-admin-icon name="edit"/>Blog</a><a href="{{ url('/admin/blog?type=case_study') }}"><x-admin-icon name="file"/>Case Study</a><a href="{{ url('/admin/blog?type=insight') }}"><x-admin-icon name="bulb"/>Insight</a></div></nav></aside><main class="main"><div class="top"><h1>{{ $contentType === 'case_study' ? 'Case Studies' : ($contentType === 'insight' ? 'Insights' : 'Blog Posts') }}</h1><a class="btn" href="{{ route('admin.blog.create',['type'=>$contentType]) }}">+ Add {{ $contentType === 'case_study' ? 'Case Study' : ($contentType === 'insight' ? 'Insight' : 'Blog Post') }}</a></div>@if(session('success'))<p class="success">{{ session('success') }}</p>@endif<table class="table"><tr><th>Title</th><th>Category</th><th>Date</th><th>Status</th><th>Actions</th></tr>@forelse($posts as $post)<tr><td>{{ $post->title }}</td><td>{{ $post->category ?: '—' }}</td><td>{{ optional($post->published_at)->format('M d, Y') ?: '—' }}</td><td>{{ ucfirst($post->status) }}</td><td><div class="actions"><a class="edit-btn" href="{{ route('admin.blog.edit',$post) }}">Edit</a> <form method="post" action="{{ route('admin.blog.destroy',$post) }}" onsubmit="return confirm('Delete this post?')">@csrf @method('DELETE')<button class="delete-btn">Delete</button></form></div></td></tr>@empty<tr><td colspan="5">No {{ $contentType === 'case_study' ? 'case studies' : ($contentType === 'insight' ? 'insights' : 'blog posts') }} yet.</td></tr>@endforelse</table></main></div></body></html>
